// The front door: takes a checkout, reserves the items, then places the order.
const { init, inSpan, call, serve } = require('./trace');
init('gateway');

const PORTS = { orders: Number(process.env.ORDERS_PORT), inventory: Number(process.env.INVENTORY_PORT) };

function validate(cart) {
  if (!Array.isArray(cart.items) || cart.items.length === 0) throw new Error('empty cart');
  let count = 0;
  for (const item of cart.items) count += item.qty;
  return count;
}

// The shop's page, and rrweb for it to record itself with.
const fs = require('node:fs');
const files = {
  '/': { type: 'text/html', body: fs.readFileSync(`${__dirname}/shop.html`) },
  '/rrweb.js': { type: 'text/javascript', body: fs.readFileSync(`${__dirname}/rrweb.js`) },
};

serve(Number(process.env.GATEWAY_PORT), {
  '/checkout': async (cart, span, identity) => {
    const count = await inSpan('validate cart', span, () => validate(cart));
    const reserved = await call('inventory', PORTS.inventory, '/reserve', { items: cart.items }, span, identity);
    if (reserved.status !== 200) return { status: 409, body: { error: reserved.body.error, count } };
    const order = await call('orders', PORTS.orders, '/orders', { user: cart.user, items: cart.items, card: cart.card }, span, identity);
    if (order.status !== 201) {
      await call('inventory', PORTS.inventory, '/release', { items: cart.items }, span, identity);
      return { status: order.status, body: order.body };
    }
    return { status: 200, body: { orderId: order.body.orderId, total: order.body.total } };
  },
}, files);

// A tracer small enough to read in the debugger: W3C trace context over HTTP, and each span's start and end written to
// the console as one line of JSON. Replay records those lines with the exact point they were written at, so the
// extractor (../extract-session.cjs) gets every span's start and end as steps of this recording, and the epoch time
// in each line puts this recording on the same clock as the others.
const http = require('node:http');
const crypto = require('node:crypto');

const MARK = '@@TRACE@@';
let service = 'service';
let sampler = null;

const now = () => performance.timeOrigin + performance.now();
const id = (bytes) => crypto.randomBytes(bytes).toString('hex');

function mark(type, data) {
  console.log(MARK + JSON.stringify({ type, service, at: now(), ...data }));
}

/** CPU and memory of this process, every `everyMs`, the way an agent samples them. */
function sample(everyMs) {
  let last = process.cpuUsage();
  let lastAt = now();
  sampler = setInterval(function sampleCpuAndMemory() {
    const cpu = process.cpuUsage();
    const at = now();
    const used = (cpu.user - last.user + cpu.system - last.system) / 1000;
    mark('metric', { cpuPercent: Math.round((used / (at - lastAt)) * 1000) / 10, rss: process.memoryUsage().rss, heapUsed: process.memoryUsage().heapUsed });
    last = cpu;
    lastAt = at;
  }, everyMs);
}

function init(name) {
  service = name;
  // The wall clock too, which is what a browser's own timestamps (and rrweb's) are on.
  mark('clock', { pid: process.pid, epochMs: Date.now() });
  sample(100);
}

function startSpan(name, { parent = null, kind = 'internal', attributes = {} } = {}) {
  const span = { traceId: parent ? parent.traceId : id(16), spanId: id(8), parentId: parent ? parent.spanId : null, name, kind, attributes };
  mark('start', span);
  return span;
}

function endSpan(span, { error = null, attributes = {} } = {}) {
  mark('end', { traceId: span.traceId, spanId: span.spanId, status: error ? 'error' : 'ok', error, attributes });
}

/** Runs `fn` in a span of its own. */
async function inSpan(name, parent, fn, attributes) {
  const span = startSpan(name, { parent, attributes });
  try {
    const value = await fn(span);
    endSpan(span);
    return value;
  } catch (error) {
    endSpan(span, { error: error.message });
    throw error;
  }
}

const traceparent = (span) => `00-${span.traceId}-${span.spanId}-01`;
function parentFrom(headers) {
  const match = /^00-([0-9a-f]{32})-([0-9a-f]{16})-0[01]$/.exec(headers.traceparent || '');
  return match ? { traceId: match[1], spanId: match[2] } : null;
}
/** Who's asking, carried from service to service like a baggage header. */
const identityFrom = (headers) => ({
  'session.id': headers['x-client-session-id'],
  'enduser.id': headers['x-user-id'],
  'http.request_id': headers['x-request-id'],
});

