  const server = http.createServer((req, res) => {
    const file = req.method === 'GET' && files[req.url];
    if (file) {
      const span = startSpan(`GET ${req.url}`, { parent: parentFrom(req.headers), kind: 'server', attributes: { 'http.method': 'GET', 'http.route': req.url } });
      res.writeHead(200, { 'content-type': file.type });
      res.end(file.body);
      endSpan(span, { attributes: { 'http.status_code': 200 } });
      return;
    }
    let text = '';
    req.on('data', (chunk) => (text += chunk));
    req.on('end', async () => {
      if (req.url === '/ping') {
        res.end('pong');
        return;
      }
      if (req.url === '/shutdown') {
        res.end('bye');
        clearInterval(sampler);
        server.close();
        return;
      }
      const identity = identityFrom(req.headers);
      const span = startSpan(`${req.method} ${req.url}`, {
        parent: parentFrom(req.headers), kind: 'server',
        attributes: { 'http.method': req.method, 'http.route': req.url, ...identity },
      });
      let status = 500;
      let body = { error: 'no route' };
      try {
        const route = routes[req.url];
        if (route) ({ status, body } = await route(text ? JSON.parse(text) : {}, span, identity));
      } catch (error) {
        body = { error: error.message };
      }
      res.writeHead(status, { 'content-type': 'application/json' });
      res.end(JSON.stringify(body));
      endSpan(span, { error: status >= 500 ? body.error : null, attributes: { 'http.status_code': status } });
    });
  });
  server.listen(port, '127.0.0.1', () => console.log(`${service} listening on ${port}`));
}

module.exports = { init, startSpan, endSpan, inSpan, call, serve };

// Prices an order, charges it, and saves it. A payment that's down for a moment is tried again.
const { init, inSpan, call, serve, startSpan, endSpan } = require('./trace');
init('orders');

const PRICES = { espresso: 3.5, bagel: 2.25, beans: 14 };
const orders = [];

function priceOf(items, user) {
  let total = 0;
  for (const item of items) total += PRICES[item.name] * item.qty;
  const loyal = orders.filter((o) => o.user === user).length >= 2;
  return Math.round((loyal ? total * 0.9 : total) * 100) / 100;
}

async function charge(order, span, identity) {
  for (let attempt = 1; ; attempt++) {
    const paid = await call('payments', Number(process.env.PAYMENTS_PORT), '/charge', { orderId: order.id, amount: order.total, card: order.card, attempt }, span, identity);
    if (paid.status !== 503 || attempt === 2) return paid;
  }
}

serve(Number(process.env.ORDERS_PORT), {
  '/orders': async ({ user, items, card }, span, identity) => {
    const order = { id: `ord_${orders.length + 1}`, user, items, card, total: await inSpan('price order', span, () => priceOf(items, user)) };
    const paid = await charge(order, span, identity);
    if (paid.status !== 200) return { status: 402, body: { error: paid.body.error } };
    await inSpan('INSERT orders', span, async () => {
      orders.push({ ...order, receipt: paid.body.receipt });
    }, { 'db.system': 'memory', 'db.statement': 'INSERT INTO orders' });
    // After the answer's gone: tell inventory the order's final, which nothing waits for.
    const publish = startSpan('publish order.created', { parent: span, kind: 'producer' });
    setTimeout(() => {
      call('inventory', Number(process.env.INVENTORY_PORT), '/events', { type: 'order.created', orderId: order.id }, publish, identity)
        .finally(() => endSpan(publish));
    }, 5);
    return { status: 201, body: { orderId: order.id, total: order.total } };
  },
});

