// Charges a card. One card is always declined, and the processor is down for the first try of the third charge.
const { init, inSpan, serve } = require('./trace');
init('payments');

let charges = 0;

function fraudScore(amount, card) {
  let score = amount > 40 ? 30 : 5;
  if (card.endsWith('0002')) score += 70;
  return score;
}

serve(Number(process.env.PAYMENTS_PORT), {
  '/charge': async ({ orderId, amount, card, attempt }, span) => {
    charges++;
    if (charges === 3 && attempt === 1) return { status: 503, body: { error: 'processor unavailable' } };
    const score = await inSpan('fraud check', span, () => fraudScore(amount, card), { 'fraud.amount': amount });
    if (score >= 70) return { status: 402, body: { error: 'card declined' } };
    const receipt = await inSpan('authorize card', span, async () => `rcpt_${orderId}_${Math.round(amount * 100)}`);
    return { status: 200, body: { receipt } };
  },
});

