// Holds stock: reserves it for a checkout, gives it back when one fails, and hears when an order is final.
const { init, inSpan, serve } = require('./trace');
init('inventory');

const stock = new Map([['espresso', 6], ['bagel', 4], ['beans', 1]]);
const final = [];

function reserve(items) {
  for (const item of items) if ((stock.get(item.name) ?? 0) < item.qty) return item.name;
  for (const item of items) stock.set(item.name, stock.get(item.name) - item.qty);
  return null;
}

serve(Number(process.env.INVENTORY_PORT), {
  '/reserve': async ({ items }, span) => {
    const short = await inSpan('reserve stock', span, () => reserve(items));
    return short ? { status: 409, body: { error: `out of ${short}` } } : { status: 200, body: { ok: true } };
  },
  '/release': async ({ items }) => {
    for (const item of items) stock.set(item.name, stock.get(item.name) + item.qty);
    return { status: 200, body: { ok: true } };
  },
  '/events': async (event) => {
    final.push(event.orderId);
    return { status: 202, body: { seen: final.length } };
  },
});

