// extractor (../extract-session.cjs) gets every span's start and end as steps of this recording, and the epoch time
// in each line puts this recording on the same clock as the others.
const http = require('node:http');
const crypto = require('node:crypto');

const MARK = '@@TRACE@@';
let service = 'service';
let sampler = null;

const now = () => performance.timeOrigin + performance.now();
const id = (bytes) => crypto.randomBytes(bytes).toString('hex');

function mark(type, data) {
  console.log(MARK + JSON.stringify({ type, service, at: now(), ...data }));
}

/** CPU and memory of this process, every `everyMs`, the way an agent samples them. */
function sample(everyMs) {
  let last = process.cpuUsage();
  let lastAt = now();
  sampler = setInterval(function sampleCpuAndMemory() {
    const cpu = process.cpuUsage();
    const at = now();
    const used = (cpu.user - last.user + cpu.system - last.system) / 1000;
    mark('metric', { cpuPercent: Math.round((used / (at - lastAt)) * 1000) / 10, rss: process.memoryUsage().rss, heapUsed: process.memoryUsage().heapUsed });
    last = cpu;
    lastAt = at;
  }, everyMs);
}

function init(name) {
  service = name;
  // The wall clock too, which is what a browser's own timestamps (and rrweb's) are on.
  mark('clock', { pid: process.pid, epochMs: Date.now() });
  sample(100);
}

function startSpan(name, { parent = null, kind = 'internal', attributes = {} } = {}) {
  const span = { traceId: parent ? parent.traceId : id(16), spanId: id(8), parentId: parent ? parent.spanId : null, name, kind, attributes };
  mark('start', span);
  return span;
}

function endSpan(span, { error = null, attributes = {} } = {}) {
  mark('end', { traceId: span.traceId, spanId: span.spanId, status: error ? 'error' : 'ok', error, attributes });
}

/** Runs `fn` in a span of its own. */
async function inSpan(name, parent, fn, attributes) {
  const span = startSpan(name, { parent, attributes });
  try {
    const value = await fn(span);
    endSpan(span);
    return value;
  } catch (error) {
    endSpan(span, { error: error.message });
    throw error;
  }
}

const traceparent = (span) => `00-${span.traceId}-${span.spanId}-01`;
function parentFrom(headers) {
  const match = /^00-([0-9a-f]{32})-([0-9a-f]{16})-0[01]$/.exec(headers.traceparent || '');
  return match ? { traceId: match[1], spanId: match[2] } : null;
}
/** Who's asking, carried from service to service like a baggage header. */
const identityFrom = (headers) => ({
  'session.id': headers['x-client-session-id'],
  'enduser.id': headers['x-user-id'],
  'http.request_id': headers['x-request-id'],
});

/** An HTTP call to another service, in a client span whose context goes with it. */
function call(peer, port, path, body, parent, identity = {}) {
  const span = startSpan(`POST ${path}`, { parent, kind: 'client', attributes: { 'peer.service': peer, 'http.method': 'POST', 'http.url': `http://${peer}${path}` } });
  const payload = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const req = http.request({
      host: '127.0.0.1', port, path, method: 'POST',
      headers: {
        'content-type': 'application/json', 'content-length': Buffer.byteLength(payload), traceparent: traceparent(span),
        ...(identity['session.id'] ? { 'x-client-session-id': identity['session.id'] } : {}),
        ...(identity['enduser.id'] ? { 'x-user-id': identity['enduser.id'] } : {}),
        ...(identity['http.request_id'] ? { 'x-request-id': identity['http.request_id'] } : {}),
      },
    }, (res) => {
      let text = '';
      res.on('data', (chunk) => (text += chunk));
      res.on('end', () => {
        const failed = res.statusCode >= 400;
        endSpan(span, { error: failed ? `${peer} answered ${res.statusCode}` : null, attributes: { 'http.status_code': res.statusCode } });
        resolve({ status: res.statusCode, body: text ? JSON.parse(text) : null });
      });
    });
    req.on('error', (error) => {
      endSpan(span, { error: error.message });
      reject(error);
    });
    req.end(payload);
  });
}

/** An HTTP server whose every request is a server span. `routes` answers `{ status, body }`. */
function serve(port, routes, files = {}) {
  const server = http.createServer((req, res) => {
    const file = req.method === 'GET' && files[req.url];
    if (file) {
      const span = startSpan(`GET ${req.url}`, { parent: parentFrom(req.headers), kind: 'server', attributes: { 'http.method': 'GET', 'http.route': req.url } });
      res.writeHead(200, { 'content-type': file.type });
      res.end(file.body);
      endSpan(span, { attributes: { 'http.status_code': 200 } });
      return;
    }
    let text = '';
    req.on('data', (chunk) => (text += chunk));
    req.on('end', async () => {
      if (req.url === '/ping') {
        res.end('pong');
        return;
      }
      if (req.url === '/shutdown') {
        res.end('bye');
        clearInterval(sampler);
        server.close();
        return;
      }
      const identity = identityFrom(req.headers);
      const span = startSpan(`${req.method} ${req.url}`, {
        parent: parentFrom(req.headers), kind: 'server',
        attributes: { 'http.method': req.method, 'http.route': req.url, ...identity },
      });
      let status = 500;
      let body = { error: 'no route' };
      try {
        const route = routes[req.url];
        if (route) ({ status, body } = await route(text ? JSON.parse(text) : {}, span, identity));
      } catch (error) {
        body = { error: error.message };
      }
      res.writeHead(status, { 'content-type': 'application/json' });
      res.end(JSON.stringify(body));
      endSpan(span, { error: status >= 500 ? body.error : null, attributes: { 'http.status_code': status } });
    });
  });
  server.listen(port, '127.0.0.1', () => console.log(`${service} listening on ${port}`));
}

module.exports = { init, startSpan, endSpan, inSpan, call, serve };
